import { describe, it, expect } from 'vitest';
import git from 'isomorphic-git';
import {
  createTestContext,
  recordEvent,
  replayEvents,
  getDatabase,
  insertNode,
  type HiveContext,
  type Node,
} from '@hive/core';

const branch = 'hive-test';

async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}

async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('replay must not drop a status event that precedes its node in log order', () => {
  it('applies G -> completed even when the status commit is replayed before the add commit', async () => {
    const { ctx } = await bootstrap();

    const nodeId = 'node-g-0000000';

    // Teammate's slow clock: the `status: G -> completed` commit is written into the
    // branch history BEFORE the `add G` commit. On a full rebuild parseGitLog's result is
    // reversed to "oldest first", so replayEvent sees the status event while G is still
    // absent from the db -- the exact ordering the witness describes.
    const statusMsg = [
      `status: ${nodeId.substring(0, 7)} -> completed`,
      '',
      'id: status-evt-00000001',
      'type: status',
      `node: ${nodeId}`,
      'status: completed',
      'parents: []',
    ].join('\n');
    await ctx.git.commitToBranch(statusMsg, branch, { allowEmpty: true });

    const addMsg = [
      'decision: Goal G',
      '',
      `id: ${nodeId}`,
      'type: decision',
      'confidence: 90',
    ].join('\n');
    await ctx.git.commitToBranch(addMsg, branch, { allowEmpty: true });

    // Full rebuild: clear the branch, then replay every commit oldest-first, i.e. the
    // status event first (node missing -> dropped at lines 390-392) and the add event
    // second. There is no second pass to recover the dropped status.
    await replayEvents(ctx, branch, true);

    // Current status lives in state_refs -> state_transitions (nodes.status is a constant).
    // A causally-aware replay ends with G's status ref pointing at a 'completed'
    // transition; a replay that drops the early status event leaves no such ref at all.
    const db = getDatabase(ctx);
    const row = db.prepare(
      `SELECT st.new_value AS v\n         FROM state_refs sr\n         JOIN state_transitions st ON st.change_id = sr.ref_change_id\n        WHERE sr.node_id = ? AND sr.property = 'status' AND sr.branch = ?`,
    ).get(nodeId, branch) as { v: string } | undefined;

    expect(row?.v).toBe('completed');
  });
});
